def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    # Replace the program name with the fully qualified path of the executable
    if os.name == 'nt':
        exe_basename = os.path.basename(cmd[0])
        if exe_basename == 'python.exe' or exe_basename == 'pythonw.exe':
            exe_fullname = cmd[0]
            while os.path.islink(exe_fullname):
                exe_fullname = os.readlink(exe_fullname)
                if not os.path.isabs(exe_fullname):
                    exe_fullname = os.path.join(os.path.dirname(exe_fullname), exe_fullname)
            cmd = (exe_fullname,) + cmd[1:]

    # Fix command line arguments that contain space or double quotes for windows
    if os.name == 'nt':
        new_cmd = []
        for arg in cmd:
            if ' ' in arg or '"' in arg:
                new_arg = '^' if '^' not in arg else arg.replace('^', '^^')
                new_cmd.append('"' + new_arg + '"')
            else:
                new_cmd.append(arg)
        cmd = tuple(new_cmd)

    return cmd

