def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class TTLCache(dict):
        """A cache dictionary that uses a Least Recently Used (LRU)
        algorithm with a per-item time-to-live (TTL) value.
        """

        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def _getitem(self, key, silent=False):
            if key not in self:
                if not silent:
                    raise KeyError(key)
                return None
            now = self.timer()
            if self.ttl != 0 and now - self[key][1] > self.ttl:
                del self[key]
                return None
            self[key][1] = now  # update timestamp
            return self[key][0]

        def _setitem(self, key, value):
            if key in self:
                now = self.timer()
                self[key] = (value, now)
            else:
                now = self.timer()
                self[key] = (value, now)
                if len(self) > self.maxsize:
                    self._popitem()

        def _popitem(self):
            now = self.timer()
            to_pop = None
            for key, (_, time_added) in self.items():
                if time_added < now:
                    to_pop = key
            if to_pop is not None:
                del self[to_pop]

        def __getitem__(self, key):
            return self._getitem(key)

        def __setitem__(self, key, value):
            self._setitem(key, value)

        def __delitem__(self, key):
            del self[key]

    def ttl_cache_wrapper(func):
        cache = TTLCache(maxsize, ttl, timer, typed)

        def inner(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            try:
                return cache[key]
            except KeyError:
                pass  # key not found
            value = func(*args, **kwargs)
            cache[key] = value
            return value

        return inner

    return ttl_cache_wrapper

