class LFUCache(dict):
    def __init__(self, maxsize, typed=False):
        super().__init__()
        self.maxsize = maxsize
        self.first_seen = collections.Counter()
        self.last_seen = collections.deque()
        self.typed = typed

    def move_last(self, key):
        self.last_seen.remove(key)
        self.last_seen.append(key)

    def move_first(self, key):
        self.first_seen[key] += 1
        if self.typed:
            # Remember the type that was used to save the value
            self[key] = self[key]

    def get(self, k):
        self.move_last(k)
        return super().get(k)

    def __setitem__(self, k, v):
        self.move_last(k)
        super().__setitem__(k, v)

        while len(self.last_seen) > self.maxsize:
            evicted_key = self.last_seen.popleft()
            self.pop(evicted_key)

