def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    """
    seen = set()
    minimum = []
    for cls in sorted(classes, key=lambda cls: cls.__name__):
        if cls in seen:
            continue
        seen.add(cls)
        minimum.append(cls)
        for b in minimalBases(cls.__bases__):
            minimum.append(b)
    return tuple(minimum)

def minimalBases(classes):
