        raise TypeError("last_applied_manifest must be a dictionary")

    if not isinstance(observer_schema, dict):
        raise TypeError("observer_schema must be a dictionary")

    if not isinstance(response, dict):
        raise TypeError("response must be a dictionary")

    for key in observer_schema:
        if key not in response:
            raise KeyError(f"{key} is not present in response")

        value = response[key]
        if key in last_applied_manifest and isinstance(last_applied_manifest[key], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], observer_schema[key], value)
