def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    *sql* (str or bytes) is the SQL query.

    *params* (dict or list) contains the set of in-style parameters. It maps each parameter (str or int) to value. If .SQLParams.in_style is a named parameter style, then params must be a dict. If .SQLParams.in_style is an ordinal parameter style, then params must be a list.

    Returns a tuple containing:

    - The formatted SQL query (str or bytes).

    - The set of converted out-style parameters (dict or list).
    """
    # Convert the in-style parameters to out-style parameters
    out_params = {}
    if isinstance(params, dict):
        # Named parameter style
        for key in params:
            out_params[key] = params[key]
    else:
        # Ordinal parameter style
        for i, param in enumerate(params):
            out_params[i] = param

    # Replace the in-style parameters with out-style parameters in the SQL query
    for in_style_param, out_style_param in self.in_style_map.items():
        sql = sql.replace(in_style_param, out_style_param % out_params)

    return sql, out_params

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters. It maps each parameter (str or int) to value.
    :type params: dict or list
    :return: The formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple
    """
    if isinstance(sql, str):
        sql = bytes(sql, "utf-8")
    if isinstance(params, dict):
        params = {k.encode("utf-8"): v for k, v in params.items()}
        params = list(params.values())
    if isinstance(params, list):
        params = [p.encode("utf-8") for p in params]
    return (sql, params)

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :param params: The set of in-style parameters.
    :return: The formatted SQL query and the set of converted out-style parameters.
    """
    if self.in_style == "NAMED":
        if not isinstance(params, dict):
            raise ValueError("params must be a dict for NAMED in-style")
    else:
        if not isinstance(params, list):
            raise ValueError("params must be a list for QUOTED in-style")

    query = sql % params
    if self.out_style == "NAMED":
        out_params = {f"@{key}": value for (key, value) in params.items()}
    else:
        out_params = [f"@{index}" for index, value in enumerate(params)]

    return query, out_params

def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes
    :param params: The set of in-style parameters.
    :type params: dict or list
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple
    """
    # Check the input types
    if not isinstance(sql, (str, bytes)):
        raise ValueError("'sql' must be a string or bytes")
    if not isinstance(params, (dict, list)):
        raise ValueError("'params' must be a dictionary or a list")

    # Get the parameter style and the list of parameters
    parameter_style = self.in_style
    parameters = params

    # Convert the parameters to out-style parameters if necessary
    if parameter_style == ParameterStyle.IN_STYLE:
        parameters = []
        for key, value in params.items():
            if isinstance(key, int):
                parameters.append(value)
            else:
                parameters.append((key, value))
    elif parameter_style == ParameterStyle.NAMED:
        parameters = {}
        for key, value in params.items():
            if isinstance(key, str):
                parameters[key] = value
            else:
                raise ValueError("Parameter name is not a string")

    # Format the SQL query
    formatted_sql = sql.format(*parameters)

    # Return the formatted SQL query and the set of converted out-style parameters
    return formatted_sql, parameters

