def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.

    """
    # Check path is a valid directory
    directory_exists(path)

    # Check for OCFL storage root
    if pyfs.fs.storage_root:
        # Check if path is within storage root
        if not os.path.commonpath([path, pyfs.fs.storage_root]):
            from ocfl_validator.errors import OCFLValidityError
            raise OCFLValidityError(
                "Object path '{}' is not within the storage root '{}'".format(path, pyfs.fs.storage_root)
            )

    # Check for OCFL version
    if pyfs.fs.version:
        # Check if path has verison path
        if not os.path.exists(os.path.dirname(path) + ".v" + pyfs.fs.version):
            from ocfl_validator.errors import OCFLValidityError
            raise OCFLValidityError(
                "Object path '{}' does not have version '{}'".format(path, pyfs.fs.version)
            )

    # Check for OCFL extension
    if pyfs.fs.extension:
        # Check if path has extension
        if not os.path.basename(path).endswith("-" + pyfs.fs.extension):
            from ocfl_validator.errors import OCFLValidityError
            raise OCFLValidityError(
                "Object path '{}' does not have extension '{}'".format(path, pyfs.fs.extension)
            )

    # Check for OCFL unique root
    if pyfs.fs.unique_root:
        # Check if unique root already exists
        if os.path.isdir(os.path.join(pyfs.fs.storage_root, ".unique", str(pyfs.fs.unique_root))):
            from ocfl_validator.errors import OCFLValidityError
            raise OCFLValidityError(
                "Unique root '{}' already exists".format(pyfs.fs.unique_root)
            )

    return True

