def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of manifest files to check for digests
    :param digests_used: List of digests used in the project
    """

    # Iterate over the manifest files and check if all needed digests are present
    for manifest_file in manifest_files:
        digests_in_manifest = self._get_digests_from_manifest(manifest_file)
        for digest in digests_in_manifest:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is not used in the project")

    # Iterate over the used digests and check if all are present in the manifest
    for digest in digests_used:
        if digest not in digests_in_manifest:
            raise ValueError(f"Digest {digest} is not present in the manifest")

    # If all checks are successful, return a list of tuples containing the manifest file and the used digest
    return [(manifest_file, digest) for manifest_file in manifest_files for digest in digests_used]

