def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    Args:
        manifest_files: List of manifest files.
        digests_used: List of digests used.
    """
    # Check that all manifest files are present
    for manifest_file in manifest_files:
        if not os.path.isfile(manifest_file):
            raise ValueError("Manifest file '{}' does not exist".format(manifest_file))

    # Check that all digests in manifest are used
    for digest in digests_used:
        if digest not in self.digests:
            raise ValueError("Digest '{}' not found in any file".format(digest))

    # Check that all used digests are present in the manifest
    for digest_used in digests_used:
        if digest_used not in self.manifest_digests:
            raise ValueError("Digest '{}' not found in manifest".format(digest_used))

    # Check that all files in the manifest are present in the digests
    for filename in self.manifest_files:
        if filename not in self.files:
