    # Check that prior and self have the same constraints
    for constraint, bounds in self.constraints.items():
        if constraint not in prior.constraints or bounds != prior.constraints[constraint]:
            raise ValueError(f"prior does not have the same constraints as self for constraint {constraint}")

    # Check that prior and self have the same transformations
    for transformation, spec in self.transformations.items():
        if transformation not in prior.transformations or spec != prior.transformations[transformation]:
            raise ValueError(f"prior does not have the same transformations as self for transformation {transformation}")

