    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    if not version in inventory.versions:
        raise ValueError("Version is not in inventory.")

    logical_path_map = {}

    for metadata_file in inventory.versions[version].files:
        with open(metadata_file, "r") as f:
            content = f.read()

        for line in content.splitlines():
            path = line.split(" = ")[0].strip()
            logical_path_in_state = line.split(" = ")[1].strip()
            logical_path_map[logical_path_in_state] = set([metadata_file])

    for later_version in inventory.versions[version + 1:] + [inventory.default_version]:
        if later_version in inventory.versions_by_path:
            for metadata_file in inventory.versions_by_path[later_version].keys():
                with open(metadata_file, "r") as f:
                    content = f.read()

                for line in content.splitlines():
                    path = line.split(" = ")[0].strip()
                    logical_path_in_state = line.split(" = ")[1].strip()
                    if logical_path_in_state in logical_path_map:
                        logical_path_map[logical_path_in_state].add(metadata_file)
                    else:
                        logical_path_map[logical_path_in_state] = set([metadata_file])

