def extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the number and supplment from the content of the <issue>xxxx</issue> element.
    Possible values:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """

    number_and_supplment = issue.text.strip()

    if number_and_supplment == "":
        return (None, None)

    if number_and_supplment.startswith("["):
        # remove any surrounding brackets
        number_and_supplment = number_and_supplment[1:-1]

    if number_and_supplment.startswith("Suppl"):
        supplment = "Suppl"
        number = number_and_supplment[:number_and_supplment.index(" ")]
    else:
        supplment = None
        number = number_and_supplment

    return (number, supplment)

