        output += "Pretty Printing: " + str(self) + "\n"
    if isinstance(self, str):
        output += "'" + self + "'"
    elif isinstance(self, int) or isinstance(self, float):
        output += str(self)
    elif isinstance(self, bool):
        output += str(self).lower()
    elif isinstance(self, list):
        output += "["
        for i in range(len(self)):
            output += self[i].pretty(indent=indent + 4, debug=debug)
            if i < len(self) - 1:
                output += ", "
        output += "]"
    elif isinstance(self, dict):
        output += "{"
        for key, value in self.items():
            output += key + ": " + value.pretty(indent=indent + 4, debug=debug)
            if key != list(self.keys())[-1]:
                output += ", "
        output += "}"
    else:
        output += "Unknown Type: " + str(type(self))
    return output

