def _fromutc(self, dt):
        """
        Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.
        """

        if not dt.tzinfo:
            return dt

        # If the datetime is naive, simply localize it with the new timezone
        if not dt.tzinfo:
            return dt.replace(tzinfo=timezone)

        # Determine if the datetime is ambiguous and in a "fold" state
        is_fold = False
        normalized = dt.astimezone(timezone) - datetime(1970, 1, 1)
        if normalized.microseconds != 0:
            is_fold = True

        # Return the localized datetime with the correct fold state
        return timezone.localize(dt, is_dst=is_fold)

