def validate_version_inventories(self, version_dirs):
    """
    Each version directory should have an inventory up to that point.

    Keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    `version_dirs` is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.inventory
    inventories = {}
    digests = {}
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.txt')
        inventory = parse_inventory(inventory_path)
        inventories[version_dir] = inventory
        version_digests = {}
        for filename, hash in inventory.items():
            if filename not in root_inventory:
                continue
            if hash != root_inventory[filename]:
                version_digests[filename] = hash
        if version_digests:
            digests[version_dir] = version_digests
    return inventories, digests

def find_path_type(path):
    """
    Returns a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path.endswith("/"):
        path += "/"
    for item in os.listdir(path):
        if item.startswith("0=*"):
            return "root"
        elif item.startswith("1=*"):
            return "object"
        elif item.startswith("2=") or item.startswith("3=") or item.startswith("4="):
            return "file"
    return "unrecognized"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isdir(path):
        for child in os.listdir(path):
            child_path = os.path.join(path, child)
            if child_path.endswith("NAM'):
                with open(child_path, 'r') as f:
                    first_line = f.readline()
                    if first_line.startswith('0=*'):
                        return 'root'
            elif child_path.endswith("nt.xml"):
                return 'object'
            else:
                return 'file'
    else:
        return 'file'

