    result: List[Tuple[ruamel.yaml.nodes.ScalarNode, ruamel.yaml.nodes.MappingNode]] = []

    for key, value in nodes:
        if result:
            for existing_key, existing_value in result:
                if key.value == existing_key.value:
                    for subkey, subvalue in value.value:
                        for existing_subkey, existing_subvalue in existing_value.value:
                            if subkey.value == existing_subkey.value:
                                if isinstance(subvalue, ruamel.yaml.nodes.MappingNode) and isinstance(existing_subvalue, ruamel.yaml.nodes.MappingNode):
                                    subvalue.value = deep_merge_nodes([(subkey, subvalue), (existing_subkey, existing_subvalue)])
                                elif subvalue != existing_subvalue:
                                    existing_value.value.remove((existing_subkey, existing_subvalue))
                                    existing_value.value.append((subkey, subvalue))
                                    break
                            elif subvalue != existing_subvalue:
                                existing_value.value.remove((existing_subkey, existing_subvalue))
                                existing_value.value.append((subkey, subvalue))
                                break
                        else:
                            existing_value.value.append((subkey, subvalue))
                    break
            else:
                result.append((key, value))
        else:
            result.append((key, value))

    return result

