    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    # Initialize an empty dictionary to store the combined values
    combined_dict = {}

    # Loop through the iterable of dictionaries
    for d in dicts:
        # Loop through the key-value pairs in the current dictionary
        for k, v in d.items():
            # If the key is already in the combined dictionary, add the value to it
            if k in combined_dict:
                combined_dict[k] += v
            # Otherwise, add the key-value pair to the combined dictionary
            else:
                combined_dict[k] = v

    # Return the combined dictionary
    return combined_dict
