def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    number = abs(number)
    if number == 0:
        return ''.join(alphabet[0])

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None and len(digits) < padding:
        digits.extend([alphabet[0]] * (padding - len(digits)))

    return ''.join(digits[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number == 0:
        return "0"
    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    if padding:
        return "".join(digits).rjust(padding, "0")
    else:
        return "".join(digits)

