def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        # Verify the tentative candidate
        if not issubclass(candidate, iface):
            raise InvalidCandidateError('Tentative candidate does not match interface')
    else:
        # Verify the permanent candidate
        if not issubclass(candidate, iface):
            raise InvalidCandidateError('Permanent candidate does not match interface')

    # Verify the candidate's implementations
    for method in iface.getMethodNames():
        # Ignore special methods
        if method.startswith('__') and method.endswith('__'):
            continue

        # Verify the implementation
        impl_name = '_{}'.format(method)
        if hasattr(candidate, impl_name):
            impl = getattr(candidate, impl_name)
            if not callable(impl):
                raise InvalidCandidateError('Method {} must be callable'.format(impl_name))
        else:
            raise InvalidCandidateError('Method {} must exist'.format(impl_name))

