def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    signed_elements = find_signed_elements(doc)
    for signed_element in signed_elements:
        if signed_element.get('Id') not in signature['SignedElementIds']:
            raise ValueError("Signed element has incorrect Id value")
        if signed_element[SIGNATURE_TAG_NAME]['KeyInfo']['X509Data']['X509Certificate'] != public_key:
            raise ValueError("Signed element is not signed with the expected public key")
        verify_signature(signed_element, signature)
        return True

