def parse_xrd(document: str) -> Dict:
    """
    Parse a Diaspora webfinger in XRD format.

    https://xrd.googlecode.com/svn/trunk/spec/rfc6415.html
    """
    xrd = xml.etree.ElementTree.fromstring(document)
    links = {}
    for link in xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
        rel = link.attrib["{%s}rel" % NS_XRD]
        href = link.attrib["{%s}href" % NS_XRD]
        title = link.attrib.get("{%s}title" % NS_XRD, None)
        links[rel] = {
            "href": href,
            "title": title,
        }
    return links

