def _include_groups(parser, groups, exclude=None):
    """
    Resolves the include dict directive in the spec files.

    :param parser:
    :param groups:
    :param exclude:
    :return:
    """
    resolved_groups = {}
    for key, path in groups.items():
        if exclude and key in exclude:
            continue
        try:
            resolved_groups[key] = parser.resolve(path)
        except KeyError:
            pass
    return resolved_groups

def _include_groups(parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if key == 'directives':
            if value == 'include_dict':
                # Handle include dict directive
                self._include_dict()
            elif value == 'include_dict_items':
                # Handle include dict items directive
                self._include_dict_items()

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    This method resolves the defaults for the arguments in the current spec, preferring values from the spec over other sources.
    """
    defaults = {}
    for arg in self.spec.args:
        # Check if the arg has a default value defined in the spec
        if arg.default is not None:
            defaults[arg.name] = arg.default

        # Check if there are any environment variables that can set the default value of the arg
        env_var_name = self._get_env_var_name(arg.name)
        if env_var_name and env_var_name in os.environ:
            env_var_value = os.environ[env_var_name]
            try:
                # Attempt to convert the string value of the environment variable to the appropriate type
                env_var_value = self._convert_env_var_value(env_var_value, arg.type_)
            except (ValueError, TypeError):
                # If the conversion fails, use the string value instead
                env_var_value = str(env_var_value)
            defaults[arg.name] = env_var_value

        # Check if there is a configuration file that can set the default value of the arg
        config_path = self.config_path
        if config_path and os.path.isfile(config_path):
            config_file = toml.load(config_path)
            if arg.name in config_file:
                defaults[arg.name] = arg.typ(config_file[arg.name])

    return defaults

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources.

        Returns:
            dict: The default configurations as set by the spec.

        Raises:
            errors.InvalidSpecError: The spec contains invalid arguments.
        """
        defaults = {}
        for arg in self.spec:
            if not isinstance(arg, _BaseOpt):
                raise errors.InvalidSpecError('Unable to resolve default for non-Option type')

            # if there is a default set, add it to the defaults dict
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

            # if we have a dict option, build the defaults for its spec.
            # if any defaults exist, use them.
            if isinstance(arg, DictOption):
                if arg.spec:
                    b = arg.spec.build_defaults()
                    if b:
                        defaults[arg.name] = b
        return defaults

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources. """
        # Get default values for all arguments from the spec
        spec_defaults = {}
        for arg in self.args:
            # Get default value for the argument from the spec
            try:
                default = arg.default
            except BaseModel.Missing:
                default = None
            spec_defaults[arg.name] = default

        # Get default values for all arguments from other sources
        other_defaults = {}
        for arg in self.args:
            # Get default value for the argument from other sources
            default = arg.get_default()
            if default is not None:
                other_defaults[arg.name] = default

        # Combine spec and other default values
        defaults = {**spec_defaults, **other_defaults}
        return defaults

def get_spec_defaults(self):
        """
        Resolve arguments' values from spec and other sources.

        Returns:
            dict: The default values for each argument based on the spec.
        """
        defaults = {}
        for arg in self.args:
            if not isinstance(arg, _BaseOpt):
                raise ValueError('Unable to build default for non-Option type')

            # if there is a default set, add it to the defaults dict
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

            # if we have a dict option, resolve the spec for its subarguments.
            if isinstance(arg, DictOption):
                if arg.scheme:
                    b = arg.scheme.resolve(self.spec)
                    if b:
                        defaults[arg.name] = b
        return defaults

