    :param answer_file_args:  the dict of arguments from files
    """
    cli_args = cli_args.copy()
    answer_file_args = answer_file_args.copy()

    deprecated_args = set(cli_args).intersection(answer_file_args)
    if deprecated_args:
        print(f"The following arguments are deprecated and will be ignored: {deprecated_args}")
        for arg in deprecated_args:
            cli_args.pop(arg)
