    :param parser_name: The command name, e.g. main, virsh, ospd, etc.
    :param values_dict: The dictionary of arguments.
    """
    for value in values_dict:
        try:
            # Try to convert to int
            values_dict[value] = int(values_dict[value])
        except ValueError:
            try:
                # Try to convert to float
                values_dict[value] = float(values_dict[value])
            except ValueError:
