def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for name, value in values_dict.items():
        if name in self.options_by_name:
            option = self.options_by_name[name]
            if option.converter is not None:
                value = option.converter(option.default, value.strip())
            else:
                try:
                    value = option.type(value.strip())
                except Exception:
                    if option.type is int:
                        raise ValueError(
                            "Invalid integer value for argument '%s' with value '%s'.", name, value)
                    elif option.type is bool:
                        raise ValueError(
                            "Invalid boolean value for argument '%s' with value '%s'.", name, value)
                    else:
                        raise ValueError(
                            "Invalid value for argument '%s' with type '%s' and value '%s'.", name, option.type, value)

            values_dict[name] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self._get_parser(parser_name)
    for arg, value in values_dict.items():
        arg_meta = parser._option_string_actions[arg]
        if arg_meta is None:
            continue
        if arg_meta.option_string == "-h" or arg_meta.option_string == "--help":
            continue
        if arg_meta.nargs == "+":
            values_dict[arg] = [
                arg_meta.const if x == "True" else x for x in value.split(",")
            ]
        else:
            values_dict[arg] = arg_meta.const if value == "True" else value

